package com.smartcity360.ejb.complaints;
import com.smartcity360.common.complaints.ComplaintService;import jakarta.annotation.security.RolesAllowed;import jakarta.ejb.*;import org.junit.jupiter.api.Test;import java.lang.reflect.Method;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ComplaintServiceContractTest{
 @Test void serviceIsStatelessAndMutationsAreRequiredTransactions()throws Exception{Class<?> type=Class.forName("com.smartcity360.ejb.complaints.ComplaintServiceBean");assertNotNull(type.getAnnotation(Stateless.class));assertTrue(ComplaintService.class.isAssignableFrom(type));assertEquals(TransactionAttributeType.SUPPORTS,type.getAnnotation(TransactionAttribute.class).value());Method submit=type.getMethod("submit",com.smartcity360.common.complaints.ComplaintSubmitCommand.class);assertEquals(Set.of("RESIDENT"),Set.of(submit.getAnnotation(RolesAllowed.class).value()));for(Method mutation:List.of(submit,type.getMethod("assign",UUID.class,com.smartcity360.common.complaints.AssignmentCommand.class),type.getMethod("start",UUID.class),type.getMethod("escalate",UUID.class,com.smartcity360.common.complaints.EscalationCommand.class),type.getMethod("resolve",UUID.class,com.smartcity360.common.complaints.ResolutionCommand.class)))assertEquals(TransactionAttributeType.REQUIRED,mutation.getAnnotation(TransactionAttribute.class).value(),mutation.getName());}
 @Test void commonContractExposesNoJpaEntities(){for(Method method:ComplaintService.class.getMethods()){assertFalse(method.getReturnType().getName().contains("persistence.model"));assertTrue(Arrays.stream(method.getParameterTypes()).noneMatch(t->t.getName().contains("persistence.model")));}}
}
